S = "Hakeem Force Academy"
QS = [
(S, "In which year did the British Parliament pass the Government of India Act that later served as Pakistan's interim constitution?", ["1919", "1935", "1939", "1946"], 1, "The Government of India Act 1935 received Royal Assent in August 1935. After independence it was adapted as the interim constitution of both dominions.", "It introduced provincial autonomy and proposed an All-India Federation that never came into being.",5368),
(S, "Which court was set up in Delhi under the Government of India Act 1935?", ["Federal Court", "Supreme Court", "Privy Council", "Chief Court"], 0, "The Act created the Federal Court of India, which started work in 1937 and was the apex court before independence.", "In Pakistan the Federal Court continued as the highest court until the Supreme Court replaced it in 1956.", -1),
(S, "What important change did the Government of India Act 1935 make in the provinces?", ["Introduced provincial autonomy", "Introduced separate electorates for the first time", "Abolished the Governors", "Created a presidential system"], 0, "The Act ended dyarchy in the provinces and gave elected ministries real control of provincial subjects, called provincial autonomy.", "Separate electorates had already been given by the Morley-Minto Reforms of 1909.", -1),
(S, "Which province was created by separating Sindh from the Bombay Presidency under the arrangements of the 1935 Act?", ["Sindh became a separate province in 1936", "Balochistan became a province in 1936", "NWFP became a province in 1936", "Bahawalpur became a province in 1936"], 0, "Sindh was separated from Bombay and became a Governor's province on 1 April 1936 under the 1935 Act.", "Orissa was created as a province on the same date.", -1),
(S, "Under which plan was the partition of India announced on 3 June 1947?", ["Cabinet Mission Plan", "Cripps Plan", "Mountbatten Plan", "Wavell Plan"], 2, "Lord Mountbatten announced the partition scheme, known as the 3 June Plan or Mountbatten Plan.", "The Indian Independence Act 1947 gave legal form to this plan.", -1),
(S, "What did the Indian Independence Act 1947 create?", ["Two independent dominions, India and Pakistan", "A single federation of India", "Three dominions including Bengal", "A republic of Pakistan"], 0, "The Act divided British India into the two dominions of India and Pakistan from 15 August 1947.", "Each dominion had a Governor General and a Constituent Assembly that also acted as its legislature.", -1),
(S, "What happened to the British paramountcy over the princely states under the Indian Independence Act 1947?", ["It was transferred to Pakistan", "It lapsed", "It was extended for ten years", "It passed to the United Nations"], 1, "The Act ended British paramountcy, leaving states free to accede to either dominion.", "Each state was to decide accession on the basis of geography and the wishes of its people.", -1),
(S, "Who was the temporary chairman of the first session of Pakistan's Constituent Assembly on 10 August 1947?", ["Liaquat Ali Khan", "Maulvi Tamizuddin Khan", "Jogendra Nath Mandal", "Khawaja Nazimuddin"], 2, "Jogendra Nath Mandal, a Scheduled Caste leader from Bengal, presided until the Quaid-e-Azam was elected president.", "Mandal later served as Pakistan's first Law and Labour Minister.", -1),
(S, "On which date was Quaid-e-Azam Muhammad Ali Jinnah elected President of the Constituent Assembly of Pakistan?", ["9 August 1947", "11 August 1947", "14 August 1947", "15 August 1947"], 1, "The Assembly met at Karachi on 10 August 1947 and elected the Quaid president on 11 August 1947.", "His famous address on that day spoke of religious freedom for all citizens.", -1),
(S, "In which city did the first Constituent Assembly of Pakistan hold its first session?", ["Lahore", "Dhaka", "Karachi", "Rawalpindi"], 2, "The first session was held in Karachi, then the capital, on 10 August 1947.", "Karachi remained the capital until Rawalpindi became temporary capital in the 1960s.", -1),
(S, "Which law served as the interim constitution of Pakistan from 1947 to 1956?", ["Government of India Act 1919 as amended", "Government of India Act 1935 with adaptations", "Objectives Resolution", "Lahore Resolution"], 1, "The 1935 Act, adapted by the Pakistan Provisional Constitution Order 1947, was used until the 1956 Constitution.", "Pakistan thus ran its government under a colonial law for about eight and a half years.",2575),
(S, "Which Prime Minister moved the Objectives Resolution in the Constituent Assembly on 7 March 1949?", ["Liaquat Ali Khan", "Khawaja Nazimuddin", "Chaudhry Muhammad Ali", "H. S. Suhrawardy"], 0, "Liaquat Ali Khan, the first Prime Minister, introduced it and it was passed on 12 March 1949.", "Allama Shabbir Ahmad Usmani strongly supported it in the debate.", -1),
(S, "Which scholar-politician made a key speech supporting the Objectives Resolution in the Constituent Assembly?", ["Maulana Abul Kalam Azad", "Allama Shabbir Ahmad Usmani", "Maulana Hasrat Mohani", "Sir Sikandar Hayat"], 1, "Allama Shabbir Ahmad Usmani, a leading Deobandi scholar and Assembly member, spoke strongly in its favour.", "Hindu members led by Sris Chandra Chattopadhyaya opposed the Resolution.", -1),
(S, "According to the Objectives Resolution, democracy, freedom, equality, tolerance and social justice are to be observed as enunciated by whom?", ["Islam", "The United Nations", "The Quaid-e-Azam", "Custom"], 0, "The Resolution says principles of democracy, freedom, equality, tolerance and social justice shall be fully observed as enunciated by Islam.", "It also promised adequate provision for minorities to profess and practise their religions.", -1),
(S, "Which Article of the 1973 Constitution made the Objectives Resolution a substantive part of the Constitution?", ["Article 2", "Article 2A", "Article 3", "Article 4"], 1, "Article 2A was inserted in 1985 so that the Objectives Resolution became a substantive, enforceable part of the Constitution.", "Before that, it was only a preamble to the 1973 Constitution.", -1),
(S, "Which committee was appointed by the Constituent Assembly in March 1949 to recommend the basic principles of the future constitution?", ["Basic Principles Committee", "Constitution Commission", "Muslim League Working Committee", "Board of Talimat-e-Islamia"], 0, "The Basic Principles Committee was set up on 12 March 1949, the day the Objectives Resolution was passed.", "Its first chairman was the Prime Minister, Liaquat Ali Khan.", -1),
(S, "In which year did Liaquat Ali Khan present the first report of the Basic Principles Committee?", ["1949", "1950", "1952", "1953"], 1, "The first report was presented on 28 September 1950. It proposed a two-house legislature and the head of state elected for five years.", "It was widely criticised, especially in East Bengal, as it did not give fair representation.", -1),
(S, "What was the main cause of criticism of the 1950 report of the Basic Principles Committee in East Pakistan?", ["It proposed a presidential system", "It ignored the Urdu language", "It gave West Pakistan equal seats in both houses, ignoring Bengal's larger population", "It made English the national language"], 2, "East Bengal had a majority of the population but the report offered it far less than its share, raising a major protest.", "It was shelved and later replaced by a new draft after the language riots of 1952.", -1),
(S, "Who presented the second Basic Principles Committee report in December 1952?", ["Khawaja Nazimuddin", "Liaquat Ali Khan", "Ghulam Muhammad", "Chaudhry Muhammad Ali"], 0, "Khawaja Nazimuddin, then Prime Minister, presented the revised report on 22 December 1952.", "It proposed an upper house with equal seats for both wings, which angered Punjab.", -1),
(S, "What number of seats did the Bogra Formula of October 1953 propose for the Lower House?", ["200", "250", "300", "350"], 2, "The Formula proposed a Lower House of 300 seats, with East Bengal getting 165, and an Upper House of 50 seats with equal representation of the five units.", "It introduced the principle of parity between East and West, later used in the 1956 Constitution.", -1),
(S, "Which Governor General dissolved the first Constituent Assembly on 24 October 1954?", ["Iskander Mirza", "Ghulam Muhammad", "Khawaja Nazimuddin", "Malik Firoz Khan Noon"], 1, "Ghulam Muhammad dissolved the Assembly, saying it had lost the confidence of the people.", "Maulvi Tamizuddin Khan, its President, challenged the dissolution in court.", -1),
(S, "In the Tamizuddin Khan case 1955, who was the Chief Justice of the Federal Court that upheld the dissolution?", ["A. R. Cornelius", "Muhammad Munir", "Muhammad Shahabuddin", "Hamoodur Rahman"], 1, "Chief Justice Muhammad Munir gave the majority judgment, using the Doctrine of Necessity.", "Justice A. R. Cornelius was the lone dissenting judge.", -1),
(S, "Which Federal Court judge gave the dissenting opinion in the Tamizuddin Khan case?", ["Justice Muhammad Sharif", "Justice A. R. Cornelius", "Justice Akram", "Justice Muhammad Munir"], 1, "Justice A. R. Cornelius dissented and held that the Governor General had no power to dissolve the Assembly.", "He later became Chief Justice of Pakistan from 1960 to 1968.", -1),
(S, "How many members did the second Constituent Assembly of Pakistan have?", ["40", "60", "80", "100"], 2, "The second Constituent Assembly, formed in 1955, had 80 members elected by the provincial assemblies, with equal numbers from East and West.", "It framed the 1956 Constitution under Prime Minister Chaudhry Muhammad Ali.", -1),
(S, "Who was the Prime Minister of Pakistan when the 1956 Constitution was passed?", ["Muhammad Ali Bogra", "Chaudhry Muhammad Ali", "H. S. Suhrawardy", "I. I. Chundrigar"], 1, "Chaudhry Muhammad Ali led the government that got the Constitution passed on 29 February 1956.", "He is often called the architect of the 1956 Constitution.", 1658),
(S, "Into how many parts was the 1956 Constitution divided?", ["10", "12", "13", "15"], 2, "The 1956 Constitution had 234 articles divided into 13 parts, with 6 schedules.", "The 1973 Constitution has 12 parts and 280 articles.", -1),
(S, "How many schedules did the 1956 Constitution contain?", ["Three", "Six", "Seven", "Ten"], 1, "It had 234 articles, 13 parts and 6 schedules.", "The 1973 Constitution has 7 schedules at the end of the text.", -1),
(S, "Who was sworn in as the first President of Pakistan on 23 March 1956?", ["Ghulam Muhammad", "Iskander Mirza", "Ayub Khan", "Fazlul Haq"], 1, "Iskander Mirza was the last Governor General and became the first President when the Constitution took effect.", "He was ousted by Ayub Khan in October 1958.", -1),
(S, "What day does Pakistan observe as Republic Day because of the 1956 Constitution?", ["23 March", "14 August", "6 September", "25 December"], 0, "The 1956 Constitution came into force on 23 March 1956, making Pakistan a republic.", "23 March also marks the Lahore Resolution of 1940.", -1),
(S, "Who was the last Governor General of Pakistan?", ["Ghulam Muhammad", "Iskander Mirza", "Khawaja Nazimuddin", "Muhammad Ali Jinnah"], 1, "The office ended on 23 March 1956 when Iskander Mirza became President.", "Before him came Jinnah, Nazimuddin and Ghulam Muhammad.",644),
(S, "How many wings of the country had equal seats in the National Assembly under the 1956 Constitution?", ["Parity between East and West Pakistan", "East got two thirds", "West got two thirds", "Seats by population"], 0, "The 1956 Constitution gave parity: 150 general seats each to East and West Pakistan, plus women seats.", "Parity was a compromise to remove Bengali fears over being outvoted.", -1),
(S, "Under the 1956 Constitution the Prime Minister was to be answerable to whom?", ["The President", "The National Assembly", "The Supreme Court", "The Governors"], 1, "The Prime Minister and Cabinet were collectively responsible to the National Assembly under the parliamentary system.", "The President had to appoint as Prime Minister the member likely to command a majority.", -1),
(S, "What was the term of the President under the 1956 Constitution?", ["Three years", "Four years", "Five years", "Six years"], 2, "The President was elected for five years by the members of the National Assembly and the Provincial Assemblies.", "Under the 1962 Constitution the term was also five years.", -1),
(S, "What was the highest court established by the 1956 Constitution?", ["Federal Court", "Supreme Court", "Shariat Court", "High Court"], 1, "The 1956 Constitution created the Supreme Court in place of the Federal Court.", "Its first Chief Justice under the 1956 Constitution was Muhammad Munir.", -1),
(S, "The One Unit scheme merged which provinces into one province of West Pakistan?", ["Punjab, Sindh, NWFP, Balochistan and states", "Punjab and Sindh only", "Punjab and NWFP only", "All provinces including East Bengal"], 0, "One Unit merged the western provinces, Punjab, Sindh, NWFP, Balochistan, and the princely states into West Pakistan.", "Its aim was parity with East Pakistan.", -1),
(S, "Who was the first Governor of West Pakistan, appointed in 1955?", ["Mushtaq Ahmad Gurmani", "Ghulam Muhammad", "Akhtar Hussain", "Amir Muhammad Khan"], 0, "Mushtaq Ahmad Gurmani became the first Governor, and Dr Khan Sahib the first Chief Minister.", "West Pakistan's capital was Lahore.", -1),
(S, "Which city was the capital of the province of West Pakistan?", ["Karachi", "Lahore", "Peshawar", "Quetta"], 1, "Lahore was the provincial capital of West Pakistan from 1955 to 1970.", "Karachi was the federal capital.", -1),
(S, "Who was the first Chief Minister of West Pakistan?", ["Dr Khan Sahib", "Sardar Abdur Rab Nishtar", "Mumtaz Daultana", "Feroz Khan Noon"], 0, "Dr Khan Sahib, brother of Abdul Ghaffar Khan, led the first ministry of West Pakistan in 1955.", "He was assassinated in Lahore in 1958.", -1),
(S, "Who took over power after the abrogation of the 1956 Constitution on 7 October 1958?", ["Ayub Khan as Chief Martial Law Administrator", "Yahya Khan", "Zia ul Haq", "Musa Khan"], 0, "General Ayub Khan was appointed Chief Martial Law Administrator on 7 October 1958 and became President on 27 October 1958.", "He ousted Iskander Mirza on 27 October 1958.", -1),
(S, "Which commission, formed by Ayub Khan in February 1960, drafted the 1962 Constitution?", ["Constitution Commission under Justice Shahabuddin", "Hamoodur Rahman Commission", "Munir Commission", "Cornelius Commission"], 0, "The commission was headed by Justice Muhammad Shahabuddin and submitted its report in May 1961.", "The government amended its proposals heavily.", -1),
(S, "On which date did the 1962 Constitution come into force?", ["1 March 1962", "23 March 1962", "8 June 1962", "14 August 1962"], 2, "It was announced on 1 March 1962 and enforced on 8 June 1962, when martial law was lifted.", "The National Assembly first met in Rawalpindi in June 1962.", -1),
(S, "Which person was elected President in the 1960 referendum before the 1962 Constitution?", ["Fatima Jinnah", "Ayub Khan", "Iskander Mirza", "Yahya Khan"], 1, "Ayub Khan sought a vote of confidence from the Basic Democrats in February 1960 and won as President.", "This was the first use of the Basic Democracies as an electoral body.", -1),
(S, "In which year was the Basic Democracies Order promulgated?", ["1957", "1958", "1959", "1960"], 2, "The Basic Democracies Order was issued on 26 October 1959.", "It set up a five-tier local government system.", 346),
(S, "How many tiers did the Basic Democracies system have?", ["Two", "Three", "Four", "Five"], 3, "The tiers were Union Council or Committee, Tehsil or Thana Council, District Council, Divisional Council and Provincial Development Advisory Council.", "Only the lowest tier was directly elected by the people.", -1),
(S, "Who elected the President under the 1962 Constitution?", ["Direct vote of all adults", "National Assembly only", "Electoral College of Basic Democrats", "Provincial governors"], 2, "The Electoral College consisted of Basic Democrats, 40,000 from each wing at first.", "In 1965 the number was raised to 120,000 in total.", 139),
(S, "In which year was the first presidential election held under the 1962 Constitution, in which Fatima Jinnah challenged Ayub Khan?", ["1962", "1964", "1965", "1967"], 2, "The election took place on 2 January 1965 and Ayub Khan won through the Basic Democrats.", "Fatima Jinnah was supported by the Combined Opposition Parties.", -1),
(S, "In the January 1965 presidential election, which symbol did Fatima Jinnah contest with?", ["Arrow", "Lantern", "Rose", "Plough"], 1, "Fatima Jinnah's election symbol was the lantern, while Ayub Khan's was the rose.", "She was called Madar-e-Millat, Mother of the Nation.", -1),
(S, "Who succeeded Ayub Khan as President in March 1969?", ["Zulfikar Ali Bhutto", "Yahya Khan", "Nur Khan", "Abdul Hamid Khan"], 1, "General Agha Muhammad Yahya Khan took over on 25 March 1969, imposed martial law and abrogated the 1962 Constitution.", "Ayub Khan had resigned under pressure from mass protests.", -1),
(S, "Under the 1962 Constitution, who was to take over as President if the office fell vacant?", ["Chief Justice", "Speaker of the National Assembly", "Prime Minister", "Army chief"], 1, "The Speaker of the National Assembly was to act as President for up to 90 days until an election.", "Ayub Khan's resignation letter ignored this and handed power to the Army chief.", -1),
(S, "Which Amendment of December 1963 changed the name of the State to the Islamic Republic of Pakistan under the 1962 Constitution?", ["First Amendment", "Second Amendment", "Third Amendment", "Fifth Amendment"], 0, "The First Amendment of 1963 restored the name Islamic Republic of Pakistan and made Fundamental Rights justiciable.", "The original 1962 text had called the State the Republic of Pakistan.", -1),
(S, "The 1962 Constitution set up which two Islamic bodies?", ["Advisory Council of Islamic Ideology and Islamic Research Institute", "Federal Shariat Court and Zakat Council", "Shariat Appellate Bench and Ulema Board", "Council of Elders and Majlis-e-Shura"], 0, "These two bodies were established under Part X, the Islamic provisions, to help bring laws in line with Islam.", "The Council of Islamic Ideology exists today under the 1973 Constitution.", -1),
(S, "What did the Legal Framework Order 1970 abolish?", ["The Supreme Court", "One Unit of West Pakistan", "Martial law", "The 1962 Constitution"], 1, "The LFO of 30 March 1970 dissolved One Unit and restored the four provinces on 1 July 1970.", "It also introduced one man one vote in place of parity.", -1),
(S, "How many seats were fixed for the National Assembly under the Legal Framework Order 1970?", ["300", "313", "156", "218"], 1, "The LFO fixed 313 seats in all, 300 general and 13 for women, with seats allocated by population. East Pakistan got 169 and West Pakistan 144.", "The Assembly had to frame a constitution within 120 days.", -1),
(S, "In what number of days did the LFO 1970 require the new National Assembly to frame a constitution?", ["60 days", "90 days", "120 days", "180 days"], 2, "The Assembly had to frame the constitution within 120 days of its first meeting, failing which it would be dissolved.", "The President also had to authenticate it.", -1),
(S, "On which date were the general elections held under the LFO, the first on the basis of adult franchise?", ["7 December 1970", "17 December 1970", "7 March 1971", "23 March 1971"], 0, "National Assembly polling took place on 7 December 1970 and provincial polling on 17 December 1970.", "The Awami League won 160 of 162 general seats in East Pakistan.", -1),
(S, "Which law ended martial law in April 1972 and served as the interim constitution until August 1973?", ["Provisional Constitution Order 1969", "Interim Constitution of 1972", "Legal Framework Order", "Revival of Constitution Order"], 1, "The Interim Constitution was passed on 17 April 1972 and became effective on 21 April 1972, ending martial law.", "Zulfikar Ali Bhutto remained President under it.",1947),
(S, "Which type of government did the Interim Constitution of 1972 introduce?", ["Fully presidential", "Presidential, to become parliamentary after the permanent constitution", "Fully parliamentary at once", "Military"], 1, "The Interim Constitution gave a presidential system, with parliamentary rule to follow under the permanent constitution.", "The permanent Constitution was adopted on 10 April 1973.", -1),
(S, "When did the permanent Constitution of 1973 replace the Interim Constitution?", ["10 April 1973", "12 April 1973", "14 August 1973", "23 March 1974"], 2, "It was adopted on 10 April 1973, authenticated on 12 April, and enforced on 14 August 1973.", "Fazal Ilahi Chaudhry became President and Bhutto Prime Minister.", -1),
(S, "Under which Constitution were the Basic Democrats given the status of the Electoral College for electing the President?", ["1956 Constitution", "1962 Constitution", "1973 Constitution", "Interim Constitution 1972"], 1, "The 1962 Constitution made the Basic Democrats, elected by adult franchise at Union Council level, the electors of the President and Assemblies.", "This indirect system was ended by the 1973 Constitution, which restored direct elections.", 3221),
(S, "In which year did the Federal Court of Pakistan decide the Maulvi Tamizuddin Khan case on the dissolution of the Constituent Assembly?", ["1953", "1954", "1955", "1956"], 2, "The Federal Court gave its judgment in 1955 (the Federal Court of Pakistan decision of 21 March 1955), upholding Ghulam Muhammad's action on a technical ground.", "The judgment is seen as the start of the Doctrine of Necessity in Pakistan.", -1),
]
